open(RW + "/reply_r4_template.md", "w", encoding="utf-8").write(T); open(RW + "/reply_header_r4.md", "w", encoding="utf-8").write(H)

# ---------------- tables: FRESH render (never the stale split file) ----------------
subprocess.run([sys.executable, "render_tables.py"], cwd=S, stdout=open(S + "/tables.md", "w"), stderr=subprocess.DEVNULL, check=True)
txt = open(S + "/tables.md", encoding="utf-8").read()
def section(name):
    i = txt.index("### " + name); j = txt.find("\n### ", i + 1); return txt[i:j if j > 0 else None].strip()
tabs = {"TABLE1": section("Table 1"), "TABLE2A": section("Table 2a"), "TABLE3": section("Table 3"),
        "TABLE4": section("Junction sweep").replace("### Junction sweep", "### Table 4 — junction sweep"),
        "TABLE6": section("Passive port").replace("### Passive port", "### Table 6 — passive port"), "RESIDUE": section("Residue"),
        "TABLE3C": table3c(), "TABLE8": table8(), "TABLE9": table9()}
appendix = "# Appendix tables — round-4 text (paste inside the listings comment, before the sources; both rendered fresh by render_tables.py, never from a stored split file)\n\n" + section("Table 2b") + "\n\n" + section("Table 5") + "\n"
assert section("Table 5").count("\n| ") >= 43 and "window rule shift = passive-chain latency" in section("Table 5") and "cfl = 0.4" in section("Table 5")
body = T.replace("⟨HEADER⟩", H.strip())
for k, v in tabs.items(): body = body.replace("⟨" + k + "⟩", v)
assert "⟨" not in body, [l[:80] for l in body.splitlines() if "⟨" in l][:5]

# ---------------- build-time assertions (the round-2 regression, made impossible) ----------------
t3 = tabs["TABLE3"]
assert "slots scored" in t3 and "Table 3b" in t3 and "| 30 | 5 | 10.27 |" in t3 and "| 28 | 5 | 10.22 |" in t3, "Table 3 is not the uncapped post-check table"
assert "5.40" not in t3.split("#### Table 3b")[0] and "| 5.04 |" not in t3, "a capped shift survives in Table 3"
assert "**-5.70 dB**" in tabs["RESIDUE"] and "**-5.31 dB**" in tabs["RESIDUE"] and "**(a)**" in tabs["RESIDUE"], "residue table bold value != registered key"
assert tabs["TABLE2A"].count("\n| ") >= 28, "Table 2a lost rows"
assert tabs["TABLE6"].count("\n| ") >= 11 and "junction sweep" in tabs["TABLE6"] and "| 30 | 720 |" in tabs["TABLE6"], "Table 6 lost rows"
heads = set(re.findall(r"^#{3,4} Table (\S+?)\b", body, flags=re.M)) | {"5", "2b"}
bad = []
for mt in re.finditer(r"Table (\d[a-d]?)\b", body):
    n = mt.group(1); pre = body[max(0, mt.start() - 7):mt.start()]
    if n == "7":
        if pre != "Part I ": bad.append(("bare Table 7", body[max(0, mt.start() - 40):mt.end() + 20]))
    elif n not in heads: bad.append((n, body[max(0, mt.start() - 40):mt.end() + 20]))
assert not bad, f"dangling table references: {bad[:5]}"

assert tabs["TABLE9"].count("\n| ") == 6 and "**-13.09" not in tabs["TABLE9"] and "| (iii)" in tabs["TABLE9"] and "| (iv)" in tabs["TABLE9"]
assert body.count("exits the band on both sides") == body.count("\"exits the band on both sides\"") == 1 and body.count("outside the band on both sides") == 1, "band-side wording"
for bad in ("9–10 dB", "0.523–0.525", "+0.04 to +2.6", "the promoted floor key's own denominator", "flush-sufficiency question is not addressed", "0.55–0.89", "1.43 / 1.46", "upper bound on the loading"):
    assert bad not in body, "stale round-3 phrase: " + bad
for bad in ("plus the LF half-step", "44 dB of drive", "the released coupling", "released model's own physics", "No measured number changed", "every placement\"", "7–9 dB"):
    hits = [l[:100] for l in body.splitlines() if bad in l and "withdrawn" not in l and "round 1" not in l.lower() and "round-2" not in l.lower()]
    assert not hits, (bad, hits[:2])
# split into three comments (the executive verdict, the tables, the grades/keys/limitations), each under 60,000 characters
i3 = body.index("## 3. Tables"); i4 = body.index("## 4. Grading the record")
def marker(a, b):
    return f"\n\n---\n\n**⸻ COMMENT SPLIT ⸻ paste everything above as comment {a} and what follows as comment {b} (GitHub's comment limit is 65,536 characters; each part is under 60,000) ⸻**\n\n---\n\n"
partA, partB, partC = body[:i3].rstrip() + "\n", body[i3:i4].rstrip() + "\n", body[i4:]
assert len(partA) < 60000 and len(partB) < 60000 and len(partC) < 60000, (len(partA), len(partB), len(partC))
out = partA + marker("A", "B") + partB + marker("B", "C") + partC
os.makedirs(R, exist_ok=True)
open(f"{R}/round-4-reply.md", "w", encoding="utf-8").write("# Round-4 rework of the session reply — Fable Session 2026-09-28 (paste as three comments at the marked splits, after the round-3 vote records; this is the text the round-4 assessors judge)\n\n" + out)
open(f"{R}/round-4-tables-appendix.md", "w", encoding="utf-8").write(appendix)
print("round-4-reply.md:", len(body.split()), "words,", len(body), "chars; comments A/B/C", len(partA), len(partB), len(partC), "; appendix", len(appendix))
